NotaryLaws.register({"id":"zs","abbr":"ЗС","title":{"bg":"Закон за собствеността","en":"Property Act"},"group":"civil","source":"https://lex.bg/laws/ldoc/2122102787","retrieved":"2026-10-21","partial":false,"articles":123,"inForce":"Отразена деноминацията от 05.07.1999 г.","published":"Обн. ДВ. бр.92 от 16 Ноември 1951г.","lastChange":"изм. ДВ. бр.18 от 4 Март 2022г.","items":[{"k":"a","n":"1","p":["Чл. 1. (Изм. - ДВ, бр. 31 от 1990 г.) Този закон урежда собствеността, другите вещни права и тяхното придобиване, изгубване и защита, както и владението и вписванията."]},{"k":"a","n":"2","p":["Чл. 2. (Изм. - ДВ, бр. 31 от 1990 г.) Собствеността принадлежи на държавата, на общините, на кооперациите и други юридически лица и на граждани.","(Изм. - ДВ, бр. 33 от 1996 г.) Всички видове собственост се ползуват с еднакви възможности за развитие и закрила."]},{"k":"h","t":"I. ДЪРЖАВНА И ОБЩИНСКА СОБСТВЕНОСТ"},{"k":"a","n":"3","p":["Чл. 3. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"4","p":["Чл. 4. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"5","p":["Чл. 5. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"6","p":["Чл. 6. (Изм. - ДВ, бр. 31 от 1990 г., изм. - ДВ, бр. 77 от 1991 г., изм. - ДВ, бр. 33 от 1996 г.) Собствеността на държавата и на общините е публична и частна."]},{"k":"a","n":"7","p":["Чл. 7. (Изм. - ДВ, бр. 31 от 1990 г., изм. - ДВ, бр. 33 от 1996 г.) Режимът на обектите на държавната и на общинската собственост се определя с отделни закони."]},{"k":"a","n":"8","p":["Чл. 8. (Изм. - ДВ, бр. 31 от 1990 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"9","p":["Чл. 9. (Отм. - ДВ, бр. 91 от 1988 г.)"]},{"k":"a","n":"10","p":["Чл. 10. (Отм. - ДВ, бр. 91 от 1988 г.)"]},{"k":"a","n":"11","p":["Чл. 11. (Отм. - ДВ, бр. 91 от 1988 г.)"]},{"k":"a","n":"12","p":["Чл. 12. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"13","p":["Чл. 13. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"14","p":["Чл. 14. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"15","p":["Чл. 15. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"15а","p":["Чл. 15а. (Нов - ДВ, бр. 87 от 1974 г., доп. - ДВ, бр. 31 от 1990 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"15б","p":["Чл. 15б. (Нов - ДВ, бр. 87 от 1974 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"15в","p":["Чл. 15в. (Нов - ДВ, бр. 87 от 1974 г., доп. - ДВ, бр. 31 от 1990 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"15г","p":["Чл. 15г. (Нов - ДВ, бр. 87 от 1974 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"15д","p":["Чл. 15д. (Нов - ДВ, бр. 87 от 1974 г., изм. - ДВ, бр. 91 от 1988 г., доп. - дв, бр. 31 от 1990 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"16","p":["Чл. 16. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"17","p":["Чл. 17. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"18","p":["Чл. 18. (Изм. - ДВ, бр. 33 от 1996 г., изм. - ДВ, бр. 32 от 2005 г.) Договорите, с които се извършват придобиването и разпореждането с имоти - частна държавна или общинска собственост, се сключват в писмена форма и се вписват по разпореждане на съдията по вписванията по местонахождението на имота. Нотариална форма не е необходима."]},{"k":"a","n":"19","p":["Чл. 19. (Доп. - ДВ, бр. 31 от 1990 г.) Правото на собственост върху държавни и общински недвижими имоти може да се установява и с документ, издаден въз основа на книгите, които се водят за тези имоти."]},{"k":"a","n":"20","p":["Чл. 20. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"20а","p":["Чл. 20а. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"21","p":["Чл. 21. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"22","p":["Чл. 22. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"23","p":["Чл. 23. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"24","p":["Чл. 24. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"25","p":["Чл. 25. (Изм. - ДВ, бр. 31 от 1990 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"26","p":["Чл. 26. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"27","p":["Чл. 27. (Отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"h","t":"II. ЧАСТНА СОБСТВЕНОСТ (ЗАГЛ. ИЗМ. - ДВ, БР. 31 ОТ 1990 Г.)"},{"k":"a","n":"28","p":["Чл. 28. (Изм. - ДВ, бр. 31 от 1990 г., изм. - ДВ, бр. 33 от 1996 г.) Собственост на физически и юридически лица могат да бъдат всички вещи с изключение на тези, които съгласно Конституцията на Република България са изключителна държавна собственост или по силата на закона са публична държавна или общинска собственост.","Със закон може да се забрани притежаването от физически или юридически лица на имоти и вещи, свързани с дейности, за които е установен държавен монопол."]},{"k":"a","n":"29","p":["Чл. 29. (Изм. - ДВ, бр. 26 от 1973 г., изм. - ДВ, бр. 31 от 1990 г., изм. - ДВ, бр. 33 от 1996 г., изм. - ДВ, бр. 24 от 2007 г.) Чужденци или чуждестранни юридически лица могат да придобиват право на собственост върху земя при условията на международен договор, ратифициран по реда на чл. 22, ал. 2 от Конституцията на Република България, обнародван и влязъл в сила, а чужденците - и при наследяване по закон.","Граждани на държавите - членки на Европейския съюз, или на държавите - страни по Споразумението за Европейското икономическо пространство, могат да придобиват право на собственост върху земя при спазване на изискванията, установени със закон, в съответствие с условията на Договора за присъединяване на Република България към Европейския съюз.","Юридически лица от държавите - членки на Европейския съюз, или от държавите - страни по Споразумението за Европейското икономическо пространство, могат да придобиват право на собственост върху земя по реда на ал. 2.","Чужденци и чуждестранни юридически лица могат да придобиват право на собственост върху сгради и ограничени вещни права върху недвижим имот в страната, освен ако със закон е установено друго.","Чужда държава или междуправителствена организация може да придобива право на собственост върху земя, сгради и ограничени вещни права върху недвижим имот в страната въз основа на международен договор, на закон или акт на Министерския съвет.","Чужда държава не може да придобива право на собственост върху недвижим имот в страната по наследство."]},{"k":"a","n":"29а","p":["Чл. 29а. (Нов - ДВ, бр. 24 от 2007 г.) Лицата по чл. 29, ал. 2, които не пребивават постоянно в Република България, могат да придобиват земя за втори жилищен имот след изтичането на срока, определен при условията на Договора за присъединяване на Република България към Европейския съюз."]},{"k":"h","t":"III. СЪСОБСТВЕНОСТ"},{"k":"a","n":"30","p":["Чл. 30. (Ал. 1, изм. - ДВ, бр. 31 от 1990 г.) Правото на собственост може да принадлежи и общо на две или повече лица - държавата, общините и други юридически или физически лица.","Частите на съсобствениците се считат равни до доказване на противното.","Всеки съсобственик участвува в ползите и тежестите на общата вещ съразмерно с частта си."]},{"k":"a","n":"31","p":["Чл. 31. Всеки съсобственик може да си служи с общата вещ съобразно нейното предназначение и по начин да не пречи на другите съсобственици да си служат с нея според правата им.","Когато общата вещ се използува лично само от някои от съсобствениците, те дължат обезщетение на останалите за ползата, от която са лишени, от деня на писменото поискване."]},{"k":"a","n":"32","p":["Чл. 32. Общата вещ се използува и управлява съгласно решението на съсобствениците, притежаващи повече от половината от общата вещ.","Ако не може да се образува мнозинство или ако решението на мнозинството е вредно за общата вещ, районният съд, по искане на който и да е от съсобствениците, решава въпроса, взема необходимите мерки и ако е нужно, назначава управител на общата вещ."]},{"k":"a","n":"33","p":["Чл. 33. Съсобственикът може да продаде своята част от недвижимия имот на трето лице само след като представи пред нотариуса писмени доказателства, че е предложил на другите съсобственици да купят тази част при същите условия и декларира писмено пред него, че никой от тях не е приел това предложение.","Ако декларацията по предходната алинея е неистинска или ако третото лице купи частта на съсобственика при условия, уговорени привидно във вреда на останалите съсобственици, заинтересованият съсобственик може да изкупи тази част при действително уговорените условия. Искът трябва да се предяви в двумесечен срок от продажбата.","Ако съсобственикът не плати дължимата поради изкупуването сума в месечен срок от влизането на решението в сила, това решение се счита обезсилено по право."]},{"k":"a","n":"34","p":["Чл. 34. Всеки съсобственик може, въпреки противна уговорка, да иска делба на общата вещ, освен ако законът разпорежда друго, или ако това е несъвместимо с естеството и предназначението на вещта.","Разпоредбите за делба на наследство важат съответно и за делба на съсобствен имот.","Искът за делба не се погасява с давност."]},{"k":"a","n":"35","p":["Чл. 35. (Ал. 1, изм. - ДВ, бр. 33 от 1996 г.) Доброволната делба на движими вещи на стойност над 50 лв., както и на недвижими имоти трябва да бъде извършена писмено с нотариално заверени подписи.","Когато в делбата участвуват недееспособни или отсъствуващи, необходимо е предварително разрешение на районния съд.","(Ал. 3, отм. - ДВ, бр. 31 от 1990 г.)"]},{"k":"a","n":"36","p":["Чл. 36. (Изм. - Изв., бр. 12 от 1958 г., ДВ, бр. 87 от 1974 г. и бр. 31 от 1990 г.) Съсобствеността на държавата или на общината може да бъде прекратена освен чрез делба и чрез продажба на частта на държавата или на общината, чрез отстъпване на съсобствениците на друг равностоен имот или чрез откупуване на тяхната част при условия и по ред, определени от Министерския съвет."]},{"k":"h","t":"IV. ЕТАЖНА СОБСТВЕНОСТ"},{"k":"a","n":"37","p":["Чл. 37. (Изм. - ДВ, бр. 31 от 1990 г.) Етажи или части от етажи, заедно с придадените към тях помещения в тавана или зимника, могат да принадлежат на отделни собственици - държавата, общините и други юридически или физически лица."]},{"k":"a","n":"38","p":["Чл. 38. При сгради, в които етажи или части от етажи принадлежат на различни собственици, общи на всички собственици са земята, върху която е построена сградата, дворът, основите, външните стени, вътрешните разделителни стени между отделните части, вътрешните носещи стени, колоните, трегерите, плочите, гредоредите, стълбите, площадките, покривите, стените между таванските и избените помещения на отделните собственици, комините, външните входни врати на сградата и вратите към общи тавански и избени помещения, главните линии на всички видове инсталации и централните им уредби, асансьорите, водосточните тръби, жилището на портиера и всичко друго, което по естеството си или по предназначение служи за общо ползуване.","Може да се уговори частите на сградата, които обслужват само някои от отделно притежаваните етажи или части от етажи, да бъдат общи само на лицата, чиито помещения обслужват.","Общите части не може да се делят."]},{"k":"a","n":"39","p":["Чл. 39. Съсобствениците могат да си поделят общата сграда по етажи или части от етажи.","По същия начин може да се раздели общата сграда и по съдебен ред, ако отделните етажи или части от етажи могат да се използуват самостоятелно без значителни преустройства и без неудобства по-големи от обикновените."]},{"k":"a","n":"40","p":["Чл. 40. Дяловете на отделните собственици в общите части са съразмерни на съотношението между стойностите на отделните помещения, които те притежават, изчислени при учредяването на етажната собственост. По-късни изменения в отделните помещения не се отразяват върху размера на дяловете.","При надстрояване на сграда в етажна собственост собствениците на надстроените етажи или части от етажи придобиват, срещу заплащане, собствеността и върху всички общи части на сградата, включително и върху земята. Дяловете на всички съсобственици в общите части се определят съобразно съотношението между стойностите на отделните помещения по време на завършването на строежа.","Когато собственикът на етаж или част от етаж прехвърли отделна част от своя имот на друго лице, частта на приобретателя и на отчуждителя в общите части на сградата се определя от съотношението между стойностите на прехвърлената и запазената част по време на прехвърлянето. Същото правило се прилага и при делба."]},{"k":"a","n":"41","p":["Чл. 41. Всеки собственик, съразмерно с дела си в общите части, е длъжен да участвува в разноските, необходими за поддържането или за възстановяването им, и в полезните разноски, за извършване на които е взето решение от общото събрание."]},{"k":"a","n":"42","p":["Чл. 42. (Изм. - ДВ, бр. 6 от 2009 г., в сила от 01.05.2009 г., отм. - ДВ, бр. 57 от 2011 г.)"]},{"k":"a","n":"43","p":["Чл. 43. (Изм. - ДВ, бр. 6 от 2009 г., в сила от 01.05.2009 г., отм. - ДВ, бр. 57 от 2011 г.)"]},{"k":"a","n":"44","p":["Чл. 44. (Отм. - ДВ, бр. 57 от 2011 г.)"]},{"k":"a","n":"45","p":["Чл. 45. (Доп. - ДВ, бр. 6 от 2009 г., в сила от 01.05.2009 г.) Собственикът на етаж или на част от етаж се изважда от сградата по решение на общото събрание за срок до три години:","а) ако използува или допуска да се използуват неговите помещения по начин, който излага сградата на опасност от пожар или от значителни повреди, и","б) (изм. - ДВ, бр. 33 от 1996 г.) ако систематически нарушава правилника или решенията на общото събрание за вътрешния ред в сградата или добрите нрави.","Общото събрание може да вземе решение за изваждане само след като собственикът е бил предупреден писмено от управителя, че ще бъде изваден от имота и ако и след това предупреждение не е прекратил нарушението."]},{"k":"a","n":"46","p":["Чл. 46. (Изм. - ДВ, бр. 59 от 2007 г., в сила от 01.03.2008 г., изм. - ДВ, бр. 6 от 2009 г., в сила от 01.05.2009 г.) Собственикът може да иска от районния съд отмяна на решението на общото събрание за изваждането по реда, установен в отделен закон.","Въз основа на влязлото в сила решение на общото събрание по чл. 45 управителят или председателят на управителния съвет може да поиска издаване на заповед за изпълнение по чл. 410, ал. 1 от Гражданския процесуален кодекс."]},{"k":"a","n":"47","p":["Чл. 47. (Отм. - ДВ, бр. 57 от 2011 г.)"]},{"k":"a","n":"48","p":["Чл. 48. (Отм. - ДВ, бр. 55 от 1978 г.)"]},{"k":"a","n":"49","p":["Чл. 49. (Изм. - ДВ, бр. 33 от 1996 г., изм. - ДВ, бр. 90 от 1999 г., отм. - ДВ, бр. 6 от 2009 г., в сила от 01.05.2009 г.)"]},{"k":"h","t":"V. ОГРАНИЧЕНИЯ НА СОБСТВЕНОСТТА"},{"k":"a","n":"50","p":["Чл. 50. Собственикът на недвижим имот не може да извършва такива действия в своя имот, с които се създават пречки за използуването на съседния имот по-големи от обикновените."]},{"k":"a","n":"51","p":["Чл. 51. Когато за извършването на работи в един недвижим имот е необходимо да се влезе в друг имот, собственикът на този имот е длъжен да даде достъп за това."]},{"k":"a","n":"52","p":["Чл. 52. (Изм. - ДВ, бр. 54 от 1974 г., изм. - ДВ, бр. 36 от 1979 г., изм. - ДВ, бр. 33 от 1996 г.) Не се позволява да се посаждат дървета до имота на съседа на по-малко разстояние от 3 метра за високите дървета, 1,5 метра за средните и 1 метър за ниските. Съседът може да иска разрешение от кмета на общината, района или кметството да бъдат отсечени клоните на дърветата, които се простират над неговия имот, и корените, които преминават в неговия имот. По същия ред той може да иска да бъдат преместени дърветата, които са посадени на по-близки разстояния от посочените по-горе."]},{"k":"a","n":"53","p":["Чл. 53. Ограниченията на собствеността с оглед на благоустройствени и здравни цели се уреждат с отделни закони."]},{"k":"a","n":"54","p":["Чл. 54. С решение на Министерския съвет могат да се възлагат задължения във връзка с притежаването или стопанисването на имота."]},{"k":"h","t":"VI. ВЕЩНИ ПРАВА ВЪРХУ ЧУЖДА ВЕЩ"},{"k":"a","n":"55","p":["Чл. 55. Вещни права върху чужда вещ, доколкото те са предвидени в законите, могат да се придобиват или учредяват с правна сделка, по давност или по други начини, определени в закона."]},{"k":"h","t":"1. ПРАВО НА ПОЛЗУВАНЕ"},{"k":"a","n":"56","p":["Чл. 56. Правото на ползуване включва правото да се използува вещта съгласно нейното предназначение и правото да се получават добиви от нея без тя да се променя съществено.","Ползувателят не може да отчуждава своето право."]},{"k":"a","n":"57","p":["Чл. 57. Ползувателят е длъжен да плаща разноските, свързани с ползуването, включително данъците и другите такси, да поддържа вещта в състоянието, в което я е приел, и да я върне на собственика след прекратяване на правото на ползуване.","При предаване на имота се съставя опис. При липса на опис предполага се, до доказване на противното, че имотът е предаден в добро състояние.","Ползувателят не отговаря за овехтяването и изхабяването на вещта, които се дължат на обикновената употреба.","Той е длъжен да застрахова вещта в полза на собственика и да плаща премиите за застраховката, ако не е постановено или уговорено друго."]},{"k":"a","n":"58","p":["Чл. 58. Ползувателят е длъжен да съобщава на собственика за всяко посегателство върху собствеността."]},{"k":"a","n":"59","p":["Чл. 59. Правото на ползуване се погасява със смъртта на ползувателя, ако то не е учредено за по-кратък срок.","Правото на ползуване, учредено в полза на юридическо лице, се погасява с прекратяването му, ако не е установен по-кратък срок.","Правото на ползуване се погасява и с погиването на вещта, а също и ако не се упражнява в продължение на 5 години."]},{"k":"a","n":"60","p":["Чл. 60. Сключените от ползувателя договори за наем на полски имоти остават в сила до края на текущата стопанска година, ако правото на ползуване се прекрати преди това."]},{"k":"a","n":"61","p":["Чл. 61. Собственикът може да иска от съда да прекрати правото на ползуване, ако ползувателят, въпреки отправеното му предупреждение, продължава да си служи с вещта по начин, който застрашава същата с разрушаване или със значително повреждане, ако нарушава своите съществени задължения или ако съществено променя вещта."]},{"k":"a","n":"62","p":["Чл. 62. (Изм. - ДВ, бр. 31 от 1990 г., изм. - ДВ, бр. 33 от 1996 г.) Относно правото на ползуване върху държавен или общински имот се прилагат разпоредбите на този раздел, освен ако в закон или в акт за учредяване на това право е предвидено друго."]},{"k":"h","t":"2. СОБСТВЕНОСТ ВЪРХУ ПОСТРОЙКА"},{"k":"a","n":"63","p":["Чл. 63. Собственикът може да отстъпи на друго лице правото да построи сграда върху неговата земя, като стане собственик на постройката.","Също така собственикът на земята може да прехвърли отделно от земята собствеността върху вече съществуващата постройка.","Собственост върху постройка, отделно от земята под нея, може да се създаде и чрез доброволна делба."]},{"k":"a","n":"64","p":["Чл. 64. Собственикът на постройката може да се ползува от земята само доколкото това е необходимо за използуването на постройката според нейното предназначение, освен ако в акта, с който му е отстъпено правото, е постановено друго."]},{"k":"a","n":"65","p":["Чл. 65. Когато правото на собственост върху постройката е установено със срок, след изтичането на срока собствеността върху сградата преминава безвъзмездно върху собственика на земята."]},{"k":"a","n":"66","p":["Чл. 66. Собственикът на постройката може да я продаде на трето лице при съответно приложение разпоредбите на чл. 33.","(Ал. 2 нова - ДВ, бр. 33 от 1996 г.) Правото на строеж не се погасява, ако постройката или част от нея погине, освен ако в акта за учредяването е предвидено друго.","(Ал. 3 нова - ДВ, бр. 33 от 1996 г.) Предмет на правото на строеж може да бъде и строеж под повърхността на земята.","(Ал. 4 нова - ДВ, бр. 33 от 1996 г.) Право на надстрояване и право на пристрояване се учредява за надстрояване, съответно пристрояване на съществуваща сграда."]},{"k":"a","n":"67","p":["Чл. 67. Правото да се построи сграда върху чужда земя (чл. 63, ал. 1) се погасява в полза на собственика на земята по давност, ако не се упражни в продължение на 5 години.","(Ал. 2, нова - ДВ, бр. 87 от 1974 г., изм. - ДВ, бр. 91 от 1988 г., изм. - ДВ, бр. 31 от 1990 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"h","t":"VII. ВЛАДЕНИЕ"},{"k":"a","n":"68","p":["Чл. 68. Владението е упражняване на фактическа власт върху вещ, която владелецът държи, лично или чрез другиго, като своя.","Държането е упражняване на фактическа власт върху вещ, която лицето не държи като своя."]},{"k":"a","n":"69","p":["Чл. 69. Предполага се, че владелецът държи вещта като своя, докато не се докаже, че я държи за другиго."]},{"k":"a","n":"70","p":["Чл. 70. Владелецът е добросъвестен, когато владее вещта на правно основание, годно да го направи собственик, без да знае, че праводателят му не е собственик или че предписаната от закона форма е била опорочена. Достатъчно е добросъвестността да е съществувала при възникване на правното основание.","Добросъвестността се предполага до доказване на противното.","Когато владението е предадено въз основа на предварителен договор, сключен със собственика на имота, владелецът има правата по чл. 71 и 72."]},{"k":"a","n":"71","p":["Чл. 71. Добросъвестният владелец се ползува от вещта и получава добивите, които тя е дала, до предявяването на иска за връщането и."]},{"k":"a","n":"72","p":["Чл. 72. Добросъвестният владелец може да иска за подобренията, които е направил, сумата, с която се е увеличила стойността на вещта вследствие на тези подобрения. Това увеличение се определя към деня на постановяване съдебното решение.","Той може да иска да му се заплатят необходимите разноски, които е направил за запазване на вещта.","До заплащане на подобренията и на разноските той има право да задържи вещта."]},{"k":"a","n":"73","p":["Чл. 73. Недобросъвестният владелец дължи на собственика добивите, които е получил и които е могъл да получи, както и обезщетение за ползите, от които го е лишил, като се приспаднат направените за това разноски.","Той може да иска да му се заплатят и направените от него необходими за запазването на вещта разноски."]},{"k":"a","n":"74","p":["Чл. 74. Недобросъвестният владелец може да иска за подобренията, които е направил, само по-малката сума измежду сумата на направените разноски и сумата, с която се е увеличила стойността на имота вследствие на тези подобрения.","Когато собственикът е знаел, че се правят подобрения върху имота му и не се е противопоставил, правата на владелеца се уреждат съгласно чл. 72."]},{"k":"a","n":"75","p":["Чл. 75. Владението на недвижим имот или на вещно право върху такъв имот, включително и върху сервитут, което е продължило непрекъснато повече от шест месеца, може да бъде защищавано срещу всяко нарушение. Искът може да се предяви в шестмесечен срок."]},{"k":"a","n":"76","p":["Чл. 76. Владелецът или държателят, на когото е отнета чрез насилие или по скрит начин движима или недвижима вещ, може в шестмесечен срок да иска връщането и от лицето, което я е отнело. Това не изключва правото на лицето, което е отнело вещта, да предяви иска по предходния член."]},{"k":"h","t":"VIII. ПРИДОБИВАНЕ И ИЗГУБВАНЕ ПРАВОТО НА СОБСТВЕНОСТ"},{"k":"a","n":"77","p":["Чл. 77. Правото на собственост се придобива чрез правна сделка, по давност или по други начини, определени в закона."]},{"k":"h","t":"1. ПРИДОБИВАНЕ НА ДВИЖИМА ВЕЩ ЧРЕЗ ДОБРОСЪВЕСТНО ВЛАДЕНИЕ"},{"k":"a","n":"78","p":["Чл. 78. (Ал. 1, изм. - ДВ, бр. 100 от 1997 г.) Който придобие по възмезден начин владението на движима вещ или на ценна книга на приносител на правно основание, макар и от несобственик, но без да знае това, придобива собствеността, освен когато за прехвърлянето на собствеността върху движимата вещ се изисква нотариален акт или нотариална заверка на подписите. Това правило се прилага и за придобиване на други вещни права върху движима вещ.","(Ал. 2, изм. - ДВ, бр. 31 от 1990 г.) Собственикът на открадната или загубена вещ може да я иска от добросъвестния владелец в тригодишен срок от кражбата или изгубването. Това правило не се прилага, когато владелецът е придобил вещта от държавно или общинско предприятие."]},{"k":"h","t":"2. ПРИДОБИВАНЕ ПРАВО НА СОБСТВЕНОСТ ПО ДАВНОСТ"},{"k":"a","n":"79","p":["Чл. 79. Правото на собственост по давност върху недвижим имот се придобива с непрекъснато владение в продължение на 10 години.","Ако владението е добросъвестно, правото на собственост се придобива с непрекъснато владение в продължение на 5 години."]},{"k":"a","n":"80","p":["Чл. 80. Движима вещ се придобива по давност с непрекъснато владение в продължение на 5 години.","Който придобие владението на движима вещ чрез престъпление, не може да придобие собствеността и по давност."]},{"k":"a","n":"81","p":["Чл. 81. С изгубването на владението в продължение на повече от шест месеца давността се прекъсва."]},{"k":"a","n":"82","p":["Чл. 82. Владелецът може да присъедини към своето владение и владението на праводателя си."]},{"k":"a","n":"83","p":["Чл. 83. Който докаже, че е владял в различни времена, предполага се, че е владял и в промеждутъка, ако не се докаже противното."]},{"k":"a","n":"84","p":["Чл. 84. Относно придобивната давност, освен горните правила, се прилагат съответно и чл. 113, 115, 116, 117 и 120 от Закона за задълженията и договорите."]},{"k":"a","n":"85","p":["Чл. 85. Разпоредбите за придобиване право на собственост върху недвижим имот по давност важат за придобиване по давност и на други вещни права върху такъв имот."]},{"k":"a","n":"86","p":["Чл. 86. (Изм. - ДВ, бр. 31 от 1990 г., доп. - ДВ, бр. 33 от 1996 г.) Не може да се придобие по давност вещ, която е публична държавна или общинска собственост."]},{"k":"h","t":"3. НАМЕРЕНИ ВЕЩИ"},{"k":"a","n":"87","p":["Чл. 87. Който намери движима вещ е длъжен да я предаде на собственика или на този, който я е изгубил, след прихващане или заплащане на възнаграждението и разноските."]},{"k":"a","n":"88","p":["Чл. 88. (Изм. - ДВ, бр. 36 от 1979 г., изм. - ДВ, бр. 33 от 1996 г.) Когато собственикът и изгубилият вещта не са известни, онзи, който я е намерил, е длъжен да я предаде незабавно в съответната служба \"Общинска собственост\".","Ако собственикът или изгубилият вещта я поиска в годишен срок от намирането, вещта му се предава срещу заплащане възнаграждение в размер 10% от стойността на вещта и разноските по пренасянето и пазенето. Възнаграждението може да бъде намалено от съда с оглед на имотното състояние на изгубилия вещта или когато пълният размер на възнаграждението е прекомерно висок."]},{"k":"a","n":"89","p":["Чл. 89. (Изм. - ДВ, бр. 31 от 1990 г., изм. - ДВ, бр. 33 от 1996 г.) Ако собственикът или изгубилият вещта не се намери или не се яви в годишен срок, вещта минава в собственост на общината. В този случай разпоредбата на чл. 78, ал. 2 не се прилага.","Вещи, които подлежат на бърза развала или за пазенето на които са нужни големи разноски, се продават и с получената сума се постъпва съгласно предходната алинея."]},{"k":"a","n":"90","p":["Чл. 90. (Изм. - ДВ, бр. 36 от 1979 г., отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"91","p":["Чл. 91. Заровените в земята, зазиданите или скрити по друг начин вещи, собственикът на които не може да бъде открит, стават собственост на държавата.","Лицето, което ги е намерило, има право на възнаграждение в размер на 25% от стойността."]},{"k":"h","t":"4. ПРИРАЩЕНИЯ"},{"k":"a","n":"92","p":["Чл. 92. Собственикът на земята е собственик и на постройките и насажденията върху нея, освен ако е установено друго."]},{"k":"a","n":"93","p":["Чл. 93. Добивът от вещта, като плодове, прираст от добитък, наем и други такива, принадлежи на собственика и."]},{"k":"h","t":"5. ПРЕРАБОТВАНЕ И ПРИСЪЕДИНЯВАНЕ"},{"k":"a","n":"94","p":["Чл. 94. Лицето, което е направило нова вещ от чужди материали, става собственик на вещта, ако стойността на изработването надминава стойността на материала и ако лицето не е знаело, че материалът принадлежи на друг.","В противен случай собственикът на материала става собственик на вещта, но той има право да се откаже от нея."]},{"k":"a","n":"95","p":["Чл. 95. Когато вещта е изработена от материали, които принадлежат на различни собственици, собственик на вещта е този, на когото принадлежи главният материал.","Ако нито един от материалите не може да се счете за главен, поражда се съсобственост върху вещта."]},{"k":"a","n":"96","p":["Чл. 96. В случаите на предходните два члена, онзи, който стане собственик на новата вещ, дължи обезщетение за стойността на материала или за изработването, както и за другите вреди, ако има такива."]},{"k":"a","n":"97","p":["Чл. 97. Когато чужда вещ е присъединена като част към главна вещ по такъв начин, че не би могла да се отдели без съществено повреждане на главната вещ, собственикът на тази вещ придобива правото на собственост и върху присъединената част, при задължение да обезщети нейния собственик."]},{"k":"a","n":"98","p":["Чл. 98. Принадлежността следва главната вещ, ако не е постановено или уговорено друго."]},{"k":"h","t":"6. ИЗГУБВАНЕ ПРАВОТО НА СОБСТВЕНОСТ"},{"k":"x","t":"","p":["99. Правото на собственост се изгубва, ако друг го придобие или ако собственикът се откаже от него."]},{"k":"a","n":"100","p":["Чл. 100. (Предишен текст на чл. 100, доп. - ДВ, бр. 34 от 2000 г., в сила от 01.01.2001 г.) Отказът от правото на собственост върху недвижим имот има действие само ако е извършен в писмена форма с нотариално заверен подпис и ако е вписан в имотния регистър.","(Нова - ДВ, бр. 34 от 2000 г., в сила от 01.01.2001 г.) Заявлението за отказ от правото на собственост по ал. 1 може да се оттегли до вписването на отказа в имотния регистър."]},{"k":"h","t":"7. ОТЧУЖДАВАНЕ НА ИМОТИ ЗА ДЪРЖАВНА И ОБЩЕСТВЕНА НУЖДА"},{"k":"a","n":"101","p":["Чл. 101. (Изм. - Изв., бр. 12 от 1958 г., изм. - ДВ, бр. 91 от 1988 г., изм. - ДВ, бр. 38 от 1989 г., изм. - ДВ, бр. 31 от 1990 г., изм. - ДВ, бр. 33 от 1996 г.) За особено важни нужди на държавата и общините, за които няма възможност да се задоволят по друг начин, могат да се отчуждават имоти при условия и по ред, установени със закон, след предварително и равностойно обезщетение."]},{"k":"a","n":"102","p":["Чл. 102. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"103","p":["Чл. 103. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"104","p":["Чл. 104. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"105","p":["Чл. 105. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"106","p":["Чл. 106. (Отм. - ДВ, бр. 38 от 1989 г.)"]},{"k":"a","n":"107","p":["Чл. 107. (Отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"h","t":"IX. ЗАЩИТА НА ПРАВОТО НА СОБСТВЕНОСТ"},{"k":"a","n":"108","p":["Чл. 108. Собственикът може да иска своята вещ от всяко лице, което я владее или държи без да има основание за това."]},{"k":"a","n":"109","p":["Чл. 109. Собственикът може да иска прекратяване на всяко неоснователно действие, което му пречи да упражнява своето право.","(Ал. 2 отм. - ДВ, бр. 33 от 1996 г.)"]},{"k":"a","n":"109а","p":["Чл. 109а. (Нов - ДВ, бр. 33 от 1996 г.) Собственикът на недвижим имот може да иска определяне на границите между своя и съседните имоти."]},{"k":"h","t":"X. ОБЩИ РАЗПОРЕДБИ"},{"k":"a","n":"110","p":["Чл. 110. Недвижими вещи са: земята, растенията, сградите и другите постройки и въобще всичко, което по естествен начин или от действието на човека е прикрепено трайно към земята или към постройката.","Всички други вещи, включително и енергията, са движими вещи."]},{"k":"a","n":"111","p":["Чл. 111. Разпоредбите относно недвижимите вещи се прилагат и спрямо вещните права върху недвижимите имоти, ако законът не постановява друго.","Относно всички други права се прилагат разпоредбите, които се отнасят до движимите вещи.","Разпоредбите в глави V - XI важат за всички видове собственост по чл. 2, доколкото не е постановено друго."]},{"k":"h","t":"XI. ВПИСВАНИЯ"},{"k":"a","n":"112","p":["Чл. 112. Вписват се:","а) (доп. - ДВ, бр. 87 от 1974 г., изм. - ДВ, бр. 33 от 1996 г., доп. - ДВ, бр. 34 от 2000 г., в сила от 01.01.2001 г.) всички актове, с които се прехвърля правото на собственост или се учредява, прехвърля, изменя или прекратява друго вещно право върху недвижими имоти, както и актове, с които се признават такива права;","б) договорите, с които се прехвърля наследство, в което има недвижими имоти;","в) актовете за отказване от вещни права върху недвижими имоти;","г) договорите за делба на недвижими имоти, както и съдебно разпределителни протоколи относно такива имоти;","д) молбите на кредиторите на наследодателя или на заветниците за отделяне на недвижимите имоти на наследодателя;","е) договорите за наем на недвижим имот за срок по-дълъг от една година;","ж) спогодбите по спорове относно актове, които подлежат на вписване, и","з) влезлите в законна сила съдебни решения, които заместват актовете по буква \"а\", както и решенията, с които се констатира съществуването на подлежащи на вписване актове по предходните букви;","и) (нова - ДВ, бр. 34 от 2000 г., в сила от 01.01.2001 г.) преписи от обявените завещания с предмет недвижим имот и права върху недвижим имот;","к) (нова - ДВ, бр. 100 от 2010 г., в сила от 21.12.2010 г.) молбите за отмяна на съдебни решения, подлежащи на вписване."]},{"k":"a","n":"113","p":["Чл. 113. Актовете по предходния член до вписването им не могат да се противопоставят на трети лица, които по-рано са придобили от същия собственик и вписали вещни права върху недвижимия имот."]},{"k":"a","n":"114","p":["Чл. 114. Трябва да бъдат вписани:","а) (изм. - ДВ, бр. 33 от 1996 г.) исковите молби, с които се иска разваляне, унищожаване, отменяване или признаване нищожността на актове, подлежащи на вписване по чл. 112.","Когато вписването на исковата молба е предвидено с изрична разпоредба на закона, те произвеждат спрямо трети лица действието, посочено в същата разпоредба. При липса на такава разпоредба вписването има значение само за да даде гласност на съдебния спор относно имоти;","б) (изм. и доп. - ДВ, бр. 33 от 1996 г.) исковите молби за постановяване на решение за сключване на окончателен договор, с който се прехвърля или учредява вещно право върху недвижим имот.","Придобитите вещни права и наложени възбрани след вписването не могат да се противопоставят на ищеца. Държавата или общината за вземанията си срещу праводателя, станали изискуеми до деня на прехвърлянето или учредяването на вещното право, може да обърне взискането си към имота, в чийто ръце и да се намира той, и","в) исковите молби за постановяване на други решения по чл. 112, буква \"з\". Придобитите от трети лица вещни права след вписването не могат да се противопоставят на ищеца.","На молбите по предходните букви не се дава ход в съдилищата, докато не бъдат вписани."]},{"k":"a","n":"115","p":["Чл. 115. Влезлите в законна сила решения, постановени по исковите молби по предходния член, се отбелязват по представен препис от решението.","В решението, в което се уважава искът, съдът дава шестмесечен срок на ищеца да извърши това отбелязване. След изтичането на този срок вписването на исковата молба губи действието си.","Съдът не издава препис от решението по чл. 19, ал. 3 от ЗЗД, докато ищецът не докаже, че са заплатени разноските по прехвърлянето, както и данъците и другите задължения на праводателя му към държавата.","Ако исковата молба не е вписана, решението, което е постановено по нея, няма действие спрямо трети лица, освен от деня, в който то е вписано."]},{"k":"a","n":"116","p":["Чл. 116. Подробностите относно начина на вписването и относно таксите, които се събират при вписването, се уреждат в Правилника за вписването, одобрен от Министерския съвет."]},{"k":"h","t":"Преходни разпоредби ПРЕХОДНИ ПРАВИЛА"},{"k":"p","n":"§1","p":["§ 1. Настоящият закон влиза в сила един месец след обнародването му и отменя:","1. Закона за имуществата, собствеността и сервитутите.","2. Закона за привилегиите и ипотеките.","3. Закона за държавните имоти.","4. Закона за етажната собственост.","5. Закона за жилищното строителство и стопанисване на жилищния фонд.","6. Закона за уреждане собствеността и залога на земеделски и превозни машини със значителна стойност.","7. Закона за давността.","8. Закона против спекулата с недвижими имоти.","9. Чл. 974.от Закона за гражданското съдопроизводство."]},{"k":"p","n":"§2","p":["§ 2. Чл. 84.от Закона за задължителната военна служба се изменя така:","\"При прехвърляне на моторни превозни средства продавачът и купувачът са длъжни да уведомят писмено в десетдневен срок отдела \"Контрола върху автотранспорта при Министерството на вътрешните работи\"."]},{"k":"p","n":"§3","p":["§ 3. Правото на собственост и другите вещни права, придобити до влизането на този закон в сила, се запазват."]},{"k":"p","n":"§4","p":["§ 4. Относно придобивната давност, започнала да тече при действието на отменения закон за давността, се прилагат разпоредбите на настоящия закон, ако за завършване на давността по отменения закон е нужен по-дълъг срок от предвидения в настоящия закон."]},{"k":"p","n":"§5","p":["§ 5. Препращанията в разни закони към текстовете на отменените с § 1 закони важат като препращания към съответните по съдържание текстове на настоящия закон."]},{"k":"p","n":"§6","p":["§ 6. (Нов - ДВ, бр. 87 от 1974 г.) Гражданите, на които е признато право на строеж върху урегулирани държавни дворни места, отстъпени им или заети от тях до 15.XII.1951 г. и застроени до 1.IX.1956 г., имат право при прехвърляне или отчуждаване на имотите да получат пълната цена за правото на строеж."]},{"k":"p","n":"§7","p":["§ 7. (Нов - ДВ, бр. 87 от 1974 г.) Разпоредбата на чл. 67, ал. 2 се прилага и за заварени случаи, когато имотът не е застроен и продължава да се владее от лицето, на което е отстъпено правото на строеж, или от неговите наследници, ако то не е отнето от изпълнителния комитет на общинския народен съвет до влизане в сила на тази разпоредба."]},{"k":"h","t":"КЪМ ЗАКОНА ЗА ИЗМЕНЕНИЕ И ДОПЪЛНЕНИЕ НА ЗАКОНА ЗА СОБСТВЕНОСТТА"}]});
